# On-device first, cloud fallback with consent and redaction
import re

def local_model(prompt):
    # pretend small model: confident only on short prompts
    conf = 0.9 if len(prompt.split()) <= 6 else 0.4
    return "local answer", conf

def redact(text):
    text = re.sub(r"[\w.]+@[\w.]+", "[EMAIL]", text)
    return re.sub(r"\d{3}-\d{4}", "[PHONE]", text)

def handle(prompt, consent, cloud_allowed=True, threshold=0.6):
    answer, conf = local_model(prompt)
    if conf >= threshold:
        return "on-device (conf %.1f): %s" % (conf, answer)
    if not cloud_allowed or not consent:
        return "on-device (conf %.1f), cloud not used: %s" % (conf, answer)
    return "cloud with: " + redact(prompt)

tests = [
    ("set a timer", True, True),
    ("summarise the contract mail from bob@example.com call 555-1234 about renewal terms", True, True),
    ("summarise the contract mail from bob@example.com call 555-1234 about renewal terms", False, True),
    ("summarise this long hard document with many clauses please", True, False),
]
for p, c, allowed in tests:
    print("IN :", p)
    print("OUT:", handle(p, c, allowed))
